CREATE TABLE dbo.T (Id int NOT NULL CONSTRAINT PK_T PRIMARY KEY, V int NULL)
GO
CREATE TABLE dbo.Log (N int IDENTITY NOT NULL CONSTRAINT PK_Log PRIMARY KEY, Id int NOT NULL)
GO
CREATE TRIGGER dbo.T_Log ON dbo.T AFTER INSERT, UPDATE, DELETE AS INSERT dbo.Log (Id) SELECT Id FROM inserted UNION ALL SELECT Id FROM deleted
